param([string]$PastaDestino = (Get-Location).Path)
$ErrorActionPreference = 'Stop'
$PastaDestino = [System.IO.Path]::GetFullPath($PastaDestino)
if (-not (Test-Path -LiteralPath $PastaDestino -PathType Container)) { throw 'A pasta de destino nao existe.' }
$arquivos = @'
[{"name": "LEIA-ME.txt", "data": "", "sha256": "2f0fc3c497e7b20519c28dfe65d346314cea1895e2c19de026434a25e9ada566"}, {"name": "package.json", "data": "ewogICJuYW1lIjogImNlbnRyYWwtaXB0di1wcmVtaXVtIiwKICAidmVyc2lvbiI6ICIwLjAuMCIsCiAgInByaXZhdGUiOiB0cnVlLAogICJkZXNjcmlwdGlvbiI6ICJDb25maWd1cmFjYW8gbG9jYWwgcmVjcmlhZGE7IHNlbSBwdWJsaWNhY2FvIGF1dG9tYXRpY2EuIiwKICAiZGV2RGVwZW5kZW5jaWVzIjogewogICAgIndyYW5nbGVyIjogIjQuMTUxLjEiCiAgfQp9Cg==", "sha256": "1e377dc833516047846cbf8f1e4e75ad205239a86268ab206c6eb307d43d64e6"}, {"name": "wrangler.jsonc", "data": "", "sha256": "54f82d82b49cc8edc89895587367db6461bc749294b79af55f5ca6235bdd9338"}]
'@ | ConvertFrom-Json
$pasta = Join-Path $PastaDestino ('Cloudflare-config-nova-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
New-Item -ItemType Directory -Path $pasta | Out-Null
foreach ($arquivo in $arquivos) {
    $destino = Join-Path $pasta $arquivo.name
    [System.IO.File]::WriteAllBytes($destino, [Convert]::FromBase64String($arquivo.data))
    if ((Get-FileHash -LiteralPath $destino -Algorithm SHA256).Hash.ToLowerInvariant() -ne $arquivo.sha256) { throw 'Falha ao verificar um arquivo gerado.' }
}
Write-Host ('Arquivos criados em: ' + $pasta)
Write-Host 'Nenhum arquivo existente, site ou banco foi modificado. Nada foi publicado.'
Write-Host 'O wrangler.jsonc e um rascunho: falta conferir o ID do banco e as configuracoes atuais antes de publicar.'
